return $input.all().flatMap((item,index)=>{
let angles;
try { if(item.json.error)throw new Error(item.json.error.message??item.json.error); const output=parseSocialOutput(item.json.output); angles=Array.isArray(output)?output:output?.angles??output?.angulos??(typeof output==='string'?output.split(/^\s*---+\s*$/m).filter(s=>s.trim()):[]); if(!angles.length||angles.some(a=>typeof a!=='string'||!a.trim()))throw new Error('Ângulos vazios ou inválidos.'); }catch(error){return [{json:{...base,error:{message:error.message},tweetIndex:1,contentIndex:1},pairedItem:{item:index}}];}
return angles.map((angle,part)=>({json:{...base,angle:angle.trim(),tweetIndex:part+1,contentIndex:part+1,texto:base.text+'\n\nÂngulo deste item: '+angle.trim(),error:null},pairedItem:{item:index}}));
});

